// =============================================================
// PRÉPARE UN ITEM PAR LOGICIEL × SERVEUR
// =============================================================

// 1. Récupération des données de base
const allItems = $input.all();
const mainItem = allItems.find(i => i.json.cves) || allItems[0];
const input = mainItem.json;
const cves = input.cves || [];
const existingControls = input.controls || [];

// 2. Récupération dynamique des mesures depuis 'filtre VULN'
const measures = $('filtre VULN').all().map(item => item.json);
const measureOSObj  = measures.find(m => m.clause === 'VULN-OS-01');
const measureLOGObj = measures.find(m => m.clause === 'VULN-LOG-01');

const measureIdOS  = measureOSObj  ? measureOSObj.id  : 9;
const measureIdLOG = measureLOGObj ? measureLOGObj.id : 10;

// --- Parser le CSV logiciels ---
function parseCSV(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  const lines = String(raw).split(/\r?\n/);
  if (lines.length < 2) return [];
  const headers = lines[0].split(';').map(h => h.replace(/^"|"$/g, '').trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const fields = [];
    let current = '', inQuotes = false;
    for (let j = 0; j < line.length; j++) {
      const ch = line[j];
      if (ch === '"') {
        if (inQuotes && line[j+1] === '"') { current += '"'; j++; }
        else { inQuotes = !inQuotes; }
      } else if (ch === ';' && !inQuotes) {
        fields.push(current.trim()); current = '';
      } else { current += ch; }
    }
    fields.push(current.trim());
    if (fields.length < headers.length) continue;
    const row = {};
    headers.forEach((h, idx) => { row[h] = fields[idx] || ''; });
    rows.push(row);
  }
  return rows;
}

const logiciels = parseCSV(input.logiciels);
const maxExistingId = existingControls.reduce((m, c) => Math.max(m, c.id || 0), 0);

// --- Helpers dates et calculs ---
const today = new Date(); today.setHours(0,0,0,0);
function addDays(d, n) { const r = new Date(d); r.setDate(r.getDate()+n); return r.toISOString().split('T')[0]; }
function calcPriority(s, n) {
  if (s >= 9.0 || (n >= 3 && s >= 7.0)) return 'Critical';
  if (s >= 7.0 || n >= 3) return 'High';
  if (s >= 4.0) return 'Medium';
  return 'Low';
}
const daysMap = { Critical:15, High:30, Medium:90, Low:180 };
function calcPlanDate(p) { return addDays(today, daysMap[p]||90); }
function resolvePlanDate(existing, p) {
  if (!existing || existing === '0000-00-00') return calcPlanDate(p);
  const d = new Date(existing), t = new Date(today);
  t.setDate(t.getDate()+15);
  return d <= t ? calcPlanDate(p) : existing;
}

// --- Groupements ---
const cvesByName = {};
for (const cve of cves) {
  const name = (cve.Name||'').trim();
  const st   = String(cve.CVE||'').toLowerCase().trim();
  if (!name || st==='none' || st==='unknown') continue;
  if (!cvesByName[name]) cvesByName[name] = [];
  cvesByName[name].push(cve);
}

const logicielsByName = {};
for (const log of logiciels) {
  const name = (log.name||log.Name||'').trim();
  if (!name) continue;
  if (!logicielsByName[name]) logicielsByName[name] = [];
  logicielsByName[name].push(log);
}

// --- Construction ---
const items = [];
let newIdOffset = 0;

for (const [name, cveList] of Object.entries(cvesByName)) {
  const logList = logicielsByName[name];
  if (!logList || !logList.length) continue;

  const maxScore = Math.max(...cveList.map(c => parseFloat(c['CVE Score'])||0));
  const cveIds   = [...new Set(cveList.map(c=>c.CVE).filter(Boolean))];
  const cveObs   = cveList.filter(c=>c['CVE Score']).map(c=>`${c.CVE} (score:${c['CVE Score']}, impact:${c['CVE Impact']||'N/A'})`).join('; ');

  for (const log of logList) {
    const serverName = (log['logicalServers.name']||log['logicalServer']||'').trim() || 'UNKNOWN-SERVER';
    const serverOS   = (log['logicalServers.operating_system']||log['operating_system']||'').trim();
    const isOS       = (name === serverOS);
    const clause     = isOS ? 'VULN-OS-01' : 'VULN-LOG-01';
    const measureId  = isOS ? measureIdOS : measureIdLOG;
    const maxSecNeed = Math.max(parseInt(log.security_need_c)||0, parseInt(log.security_need_i)||0, parseInt(log.security_need_a)||0, parseInt(log.security_need_t)||0);
    const priority   = calcPriority(maxScore, maxSecNeed);
    const scope      = `${name} ${(log.version||log.Version||'').trim()} | ${serverName} | ${serverOS}`;
    const existing   = existingControls.find(c => (c.scope||'').trim()===scope && c.measure_id===measureId);

    let action, controlId, planDate, noteField;
    if (!existing) {
      action='create'; controlId=maxExistingId+1+newIdOffset; planDate=calcPlanDate(priority); noteField=priority; newIdOffset++;
    } else if (existing.status===2) {
      action='create'; controlId=maxExistingId+1+newIdOffset; planDate=calcPlanDate(priority); noteField=`${priority} (recréé — précédent #${existing.id} clôturé)`; newIdOffset++;
    } else if (existing.status===1) {
      action='update'; controlId=existing.id; planDate=resolvePlanDate(existing.plan_date,priority); noteField=`⚠️ VÉRIFIER : control en cours — ${priority}`;
    } else {
      action='update'; controlId=existing.id; planDate=resolvePlanDate(existing.plan_date,priority); noteField=priority;
    }

    items.push({ json: {
      action, software_name:name, software_version:(log.version||log.Version||'').trim(), clause, measure_id:measureId,
      server_name:serverName, server_os:serverOS, priority, plan_date:planDate,
      control_id:controlId, note_field:noteField, scope, max_cve_score:maxScore,
      cve_ids:cveIds, cve_observations:cveObs, cves_filtered:cveList,
      existing_status: existing ? existing.status : null,
      existing_realisation_date: existing ? existing.realisation_date : null,
      existing_score: existing ? existing.score : null,
      security_need_c:log.security_need_c, security_need_i:log.security_need_i,
      security_need_a:log.security_need_a, security_need_t:log.security_need_t,
      rto:log.rto, rpo:log.rpo, users:log.users
    }});
  }
}

return items;

// On récupère l'élément regroupé issu de l'agrégateur
const item = $input.item.json;

// Récupération sécurisée du tableau des CVEs validées
const cvesArray = item.data || item.response || (Array.isArray(item) ? item : []);

// Si le tableau est vide, on essaie de créer un tableau avec l'item lui-même
const baseData = cvesArray.length > 0 ? cvesArray[0] : item;

// 1. Extraction propre des IDs de CVE
const cveIdsList = cvesArray.map(c => c.CVE).filter(Boolean).join(', ');

// Calcul du score max parmi les CVE réellement validées
const scores = cvesArray.map(c => parseFloat(c['CVE Score']) || 0);
const maxScoreBrut = scores.length > 0 ? Math.max(...scores) : 0;

// --- LOGIQUE D'INVERSION POUR DEMING ---
// Si vous utilisez une échelle standard CVE (0-10), 
// nous devons mapper cela vers vos niveaux (1=Rouge, 2=Orange, 3=Vert)
let scoreFinal = 3; // Par défaut Vert

if (cvesArray.some(c => c.CVE === 'Patch-Système')) {
    // Cas de l'OS sans CVE : Score de maintenance préventive (ex: 2 = Orange)
    scoreFinal = 2; 
} else {
    // Cas des CVE réelles : Votre logique d'inversion actuelle
    if (maxScoreBrut >= 7.0) scoreFinal = 1;
    else if (maxScoreBrut >= 4.0) scoreFinal = 2;
    else scoreFinal = 3;
}

// Récupération des données contextuelles
const softwareName = (baseData.software_name || 'Logiciel').trim();
const softwareVersion = (baseData.software_version || '').trim();
const serverName = baseData.server_name || 'Serveur';
const isOS = baseData.clause === 'VULN-OS-01';

// Correction 2 : Éviter le doublon de version dans le titre
let titleName = softwareName;
if (softwareVersion && !softwareName.includes(softwareVersion)) {
    titleName = `${softwareName} ${softwareVersion}`;
}

// 3. Construction du bloc d'observations
let observationsText = "";
if (cvesArray.length > 0) {
    observationsText = cvesArray.map(c => {
        if (c.CVE === 'Patch-Système') {
            return `- ${c.CVE} : ${c.RAISON_LOGIQUE || 'Maintenance préventive appliquée.'}`;
        }
        return `- ${c.CVE} (Score: ${c['CVE Score'] !== undefined ? c['CVE Score'] : 'N/A'}) : ${c.RAISON_LOGIQUE || 'Validée'}`;
    }).join('\n');
} else {
    observationsText = isOS ? "Maintenance préventive OS appliquée." : "Aucune CVE vulnérable validée.";
}

return {
    json: {
        "id": baseData.control_id || null,
        "name": `${titleName} - ${serverName} — ${cvesArray.some(c => c.CVE === 'Patch-Système') ? 'Maintenance de Sécurité' : 'Remédiation CVE'}`,
        "objective": `Corriger les CVE détectées sur ${softwareName}`,
        "input": "Inventaire CMDB, Base CVE Mercator",
        "model": "Upgrade vers version stable supérieure",
        "indicator": "0 CVE critique non patchée",
        "action_plan": `Mettre à jour ${softwareName} vers la dernière version stable. CVEs : ${cveIdsList || 'Aucune'}.`,
        "periodicity": 3,
        "plan_date": baseData.plan_date || null,
        "realisation_date": null,
        "observations": observationsText,
        "score": scoreFinal,
        "note": baseData.clause || baseData.note_field || '', 
        "next_id": null,
        "standard": null,
        "attributes": "#Corrective #Protect #Threat_and_Vulnerability_Management #Pending_Patch",
        "scope": baseData.scope || null,
        "measures": [baseData.measure_id] || null,
        "status": 0
    }
};

// 1. On récupère le JSON en entrée
const currentControl = $input.first().json;
const allDemingControls = $('get deming controls').all(); 

// 2. On récupère l'ID de mesure déjà calculé par le nœud précédent
// S'il n'existe pas, on met 9 par défaut
//const realMeasureId = currentControl.measure_id || 9;
const realMeasureId = (currentControl.measures && currentControl.measures.length > 0) 
                      ? currentControl.measures[0] 
                      : (currentControl.measure_id || 9);

console.log("DEBUG - measure_id reçu dans le nœud :", realMeasureId);

if (!realMeasureId) {
    throw new Error("ALERTE : Le champ measure_id est vide dans l'input de ce nœud !");
}
// 3. Recherche du contrôle existant (Version tolérante aux caractères spéciaux)
let recordTrouve = null;
const targetName = (currentControl.name || "").trim().replace(/\s+/g, ' ').replace(/[–—]/g, '-');

if (Array.isArray(allDemingControls)) {
  recordTrouve = allDemingControls.find(item => {
    const deming = item.json;
    if (!deming.name) return false;
    const demingName = deming.name.trim().replace(/\s+/g, ' ').replace(/[–—]/g, '-');
    return demingName === targetName;
  })?.json;
}

// 4. Calcul de la décision (Update seulement si score plus élevé)
const nouveauScoreConverti = (parseFloat(currentControl.score) || 0) > 3 ? 3 : (Math.floor(parseFloat(currentControl.score)) || 1);
let action = 'none';
let controlIdOriginal = null;

if (recordTrouve) {
  controlIdOriginal = recordTrouve.id;
  const ancienScore = (parseFloat(recordTrouve.score) || 0);

  if (nouveauScoreConverti > ancienScore) {
    action = 'update';
  } else {
    action = 'none';
  }
} else {
  action = 'create';
}

// 5. Préparation du payload final
let finalControlBody = { ...currentControl };

if (action === 'update') {
  finalControlBody = {
    id: controlIdOriginal,
    score: nouveauScoreConverti,
    observations: currentControl.observations
  };
} else if (action === 'create') {
  // Suppression de l'ID pour forcer la création côté API
  delete finalControlBody.id;
  finalControlBody.score = nouveauScoreConverti;
  // Utilisation de l'ID de mesure propre (celui qui vient du précédent nœud)
  finalControlBody.measures = [realMeasureId]; 
}

// 6. Retour propre pour les nœuds suivants
return [{
  json: {
    control: finalControlBody,
    action: action, 
    control_id: controlIdOriginal,
    status: recordTrouve ? recordTrouve.status : 0
  }
}];

const inputJson = $input.item.json;
let cvesArray = inputJson.cves_filtered || inputJson.cves || inputJson; 

// --- CORRECTION CHIRURGICALE OS SANS CVE ---
const isOS = inputJson.clause === 'VULN-OS-01' || 
             (inputJson.software_name && inputJson.server_os && inputJson.software_name.trim() === inputJson.server_os.trim());

if ((!Array.isArray(cvesArray) || cvesArray.length === 0) && isOS) {
    cvesArray = [{
        'CVE': 'Patch-Système',
        'CVE Score': 0,
        'CVE Summary': 'Maintenance et mise à jour préventive du système d\'exploitation.',
        'RAISON_LOGIQUE': 'Génération automatique (Aucune CVE critique active détectée)'
    }];
} else if (!Array.isArray(cvesArray)) {
    return [];
}
// -------------------------------------------

function normalizeVersion(versionStr) {
    if (!versionStr) return 0;
    const clean = versionStr.toString().replace(/[^0-9.]/g, '');
    if (!clean) return 0;
    const parts = clean.split('.');
    const major = (parts[0] || "0").padStart(2, '0');
    const minor = (parts[1] || "0").padStart(2, '0');
    const patch = (parts[2] || "0").padStart(2, '0');
    return parseInt(major + minor + patch, 10);
}

const appCompVer = normalizeVersion(inputJson.software_version);
const versionRegex = /(\b\d+\.\d+\.\d+\b|\b\d+\.\d+\b)/g;

return cvesArray.map(cve => {
    const originalSummary = cve['CVE Summary'] || "";
    let compSummary = originalSummary;
    let autoDecision = "INCONNU";
    let raisonMatch = "Analyse automatique";

    if (cve.CVE === 'Patch-Système') {
        autoDecision = "OUI";
        raisonMatch = cve.RAISON_LOGIQUE;
    } else if (originalSummary) {
        const textLower = originalSummary.toLowerCase();

        // --- DECOUPAGE INTELLIGENT DU TEXTE ---
        const splitKeywords = ["upgrade to", "fixed in", "fixes this", "recommended to upgrade"];
        let vulnerabilityText = textLower;
        let patchText = "";

        for (const keyword of splitKeywords) {
            if (textLower.includes(keyword)) {
                const index = textLower.indexOf(keyword);
                vulnerabilityText = textLower.substring(0, index);
                patchText = textLower.substring(index);
                break;
            }
        }

        // --- 1. ANALYSE DE LA PARTIE CORRECTIF (PATCH) ---
        let patchVersionNum = 0;
        let patchVersionRaw = "";
        if (patchText) {
            const originalPatchText = originalSummary.substring(originalSummary.toLowerCase().indexOf(patchText.substring(0, 10)));
            const patchVersionsFound = originalPatchText.match(versionRegex);
            if (patchVersionsFound && patchVersionsFound.length > 0) {
                patchVersionRaw = patchVersionsFound[0];
                patchVersionNum = normalizeVersion(patchVersionRaw);
            }
        }

        // --- 2. ANALYSE DE LA PARTIE VULNÉRABILITÉ ---
        const originalVulnText = originalSummary.substring(0, vulnerabilityText.length);
        const vulnVersionsFound = originalVulnText.match(versionRegex);

        if (vulnVersionsFound && vulnVersionsFound.length > 0) {
            const mappedVulns = vulnVersionsFound.map(v => ({ raw: v, num: normalizeVersion(v) }));
            const maxVuln = mappedVulns.reduce((max, item) => item.num > max.num ? item : max, mappedVulns[0]);
            const minVuln = mappedVulns.reduce((min, item) => item.num < min.num ? item : min, mappedVulns[0]);

            if (vulnerabilityText.includes("older") || vulnerabilityText.includes("before") || vulnerabilityText.includes("prior to") || vulnerabilityText.includes("earlier")) {
                if (appCompVer <= maxVuln.num) {
                    autoDecision = "OUI";
                    raisonMatch = `Version ${inputJson.software_version} <= version max affectee [${maxVuln.raw}]`;
                } else {
                    autoDecision = "NON";
                    raisonMatch = `Version ${inputJson.software_version} > version max affectee [${maxVuln.raw}]`;
                }
            }
            else if (vulnerabilityText.includes("through") || vulnerabilityText.includes(" to ")) {
                if (appCompVer >= minVuln.num && appCompVer <= maxVuln.num) {
                    autoDecision = "OUI";
                    raisonMatch = `Version dans l'intervalle vulnérable [${minVuln.raw}-${maxVuln.raw}]`;
                } else if (appCompVer > maxVuln.num) {
                    autoDecision = "NON";
                    raisonMatch = `Version supérieure à l'intervalle [${maxVuln.raw}]`;
                }
            }
        } 

        // --- 3. SÉCURITÉ / DOUBLE CHECK AVEC LE PATCH ---
        if (autoDecision === "INCONNU" && patchVersionNum > 0) {
            if (appCompVer < patchVersionNum) {
                autoDecision = "OUI";
                raisonMatch = `Version inférieure au correctif [${patchVersionRaw}]`;
            } else {
                autoDecision = "NON";
                raisonMatch = `Version >= au correctif [${patchVersionRaw}]`;
            }
        }
    }

    if (compSummary && cve.CVE !== 'Patch-Système') {
        compSummary = compSummary.replace(versionRegex, (match) => {
            return `${match} [${normalizeVersion(match)}]`;
        });
    }

    // --- FORCE OUI POUR LES OS ---
    if (isOS) {
        autoDecision = "OUI";
        raisonMatch = "Règle forcée : OS soumis à maintenance préventive systématique.";
    }
    // -----------------------------

    return {
        json: {
            software_name: inputJson.software_name,
            software_version: inputJson.software_version,
            CompVer: appCompVer.toString(),

            AFFECTE_LOGIQUE: autoDecision,
            RAISON_LOGIQUE: raisonMatch,

            CompCVE_Summary: compSummary,
            "CVE Summary": originalSummary,
            ...inputJson,
            ...cve
        }
    };
});

// 1. On récupère la liste complète des requêtes Mercator renvoyée par le GET
const queries = $input.all();

let targetId = null;

// 2. On cherche la requête dont le nom est "cpe"
if (Array.isArray(queries)) {
  for (const item of queries) {
    const queryData = item.json;
    if (queryData && queryData.name && queryData.name.trim() === "cpe") {
      targetId = queryData.id;
      break;
    }
  }
}

// 3. Sécurité : Si la requête n'existe pas ou a été renommée
if (!targetId) {
  throw new Error("Impossible de trouver la requête nommée 'cpe' dans Mercator. Vérifiez son nom sur l'interface.");
}

// 4. On retourne l'ID dynamique trouvé
return [{
  json: {
    mercator_query_id: targetId
  }
}];

// On traite la réponse brute de /api/controls
return items.map(item => {
    const control = item.json;

    // Extraction sécurisée
    // On récupère le 1er ID de mesure s'il existe, sinon null
    const measureId = (control.measures && control.measures.length > 0) 
        ? control.measures[0] 
        : null;

    return {
        json: {
            id: control.id,
            name: control.name,
            clause: control.clause || "", // On récupère le champ clause
            //measure_id: measureId
        }
    };
}).filter(item => {
    // Filtrage pour ne garder que ceux dont la clause commence par "VULN-"
    return item.json.clause && item.json.clause.startsWith("VULN-");
});

// On traite la réponse brute de /api/controls
const results = [];

items.forEach(item => {
    const control = item.json;

    // 1. On ne traite que si la clause commence par "VULN-"
    if (control.clause && control.clause.startsWith("VULN-")) {

        // 2. Si le champ 'controls' est un tableau, on crée un objet par ID
        if (control.controls && Array.isArray(control.controls)) {
            control.controls.forEach(controlId => {
                results.push({
                    json: {
                        id: control.id,
                        name: control.name,
                        clause: control.clause,
                        // C'est ici que l'on isole l'ID spécifique pour le merge
                        target_control_id: controlId 
                    }
                });
            });
        }
    }
});

return results;
